/* Generated by tools/gen_school_valve.py from the original roof valve event. */
#define SH_SCHOOL_ROOF_VALVE_CALLBACK 8
static void roof_valve_steps(ShTown *town, ShSavegame *save, const ShInputState *input, float dt)
{
    ShPathPoint position, look, initial_position, initial_look;
    sh_drain_camera_sample(0, false, &initial_position, &initial_look);
switch (town->step)
    {
        case 0:
            (town->controls_locked = true);

            town->school.valve.opening = 0;
            town->school.valve.running = 0;

            sh_save_event_set(save, 1364);

            town->school.valve.sound_phase = 0;
            step_set(town, town->step + 1);
        /* fall through */

        case 1:
            step_set(town, town->step + 1);
            break;

        case 2:
            valve_prompt(town, input, 40, 4, 3); 
            break;

        case 3:
            
            ladder_unfreeze(town);
            finish(town);
            break;

        case 4:
            (town->border.state = SH_BORDER_FADEINSTART);

            sh_roof_water_prepare(&s_roof_water, sh_save_event_get(save, 111));

            town->school.card_player.position.vx = -46899;
            town->school.card_player.position.vz = -53043;
            town->school.card_player.rotation.vy = 1024;
            card_warp(town);
            town->school.valve_active = true;

            (town->school.empty_hand = true);
            (town->school.empty_hand = true);

            
            ladder_camera(town, false, -50708, -4915, -57630);
            ladder_camera(town, true, -37847, -3112, -47636);

            step_set(town, town->step + 1);
        /* fall through */

        case 5:
            ladder_wait(town, dt, 6144);
            break;

        case 6:
            town->school.valve_animation_calls = 0;
            step_set(town, town->step + 1);
        /* fall through */

        case 7:
            town->school.valve_animation_calls++;
            card_animation(town, 107, dt);
            break;

        case 8:
            sh_water_pool_begin(&s_roof_water.pool, &s_roof_water.config);
            sh_water_spray_begin(&s_roof_water.pool, s_roof_water.spray, 0);
            sh_water_spray_begin(&s_roof_water.pool, s_roof_water.spray, 1);

            if (sh_save_event_get(save, 111))
            {
                sh_water_spray_begin(&s_roof_water.pool, s_roof_water.spray, 2);
            }

            (town->school.player_hidden = true);

            (town->school.drain_flare_suppressed = true);
            ladder_camera(town, false, initial_position.vx, initial_position.vy, initial_position.vz);
            ladder_camera(town, true, initial_look.vx, initial_look.vy, initial_look.vz);

            town->school.drain_ticks = 0;
            step_set(town, town->step + 1);
        /* fall through */

        case 9:
            town->school.drain_ticks += SH_Q12(dt);
            if (!sh_drain_camera_sample(town->school.drain_ticks, sh_save_event_get(save, 111), &position, &look)) {
                step_set(town, town->step + 1);
            } else {
                ladder_camera(town, false, position.vx, position.vy, position.vz);
                ladder_camera(town, true, look.vx, look.vy, look.vz);
                sh_drain_camera_light(position, look, &town->school.drain_light);
                town->school.drain_light_override = true;
            }
            break;

        case 10:
            if (sh_save_event_get(save, 111))
            {
                step_set(town, town->step + 1);
            }
            else
            {
                card_message(town, input, 41); 
            }
            break;

        case 11:
            (town->school.player_hidden = false);

            (town->school.drain_flare_suppressed = false);
            (town->school.drain_light_override = false);

            
            ladder_camera(town, false, -50708, -4915, -57630);
            ladder_camera(town, true, -37847, -3112, -47636);

            sh_roof_water_stop(&s_roof_water);

            if (sh_save_event_get(save, 111))
            {
                sh_save_event_set(save, 113);
            }

            town->school.valve.sound_phase = 0;
            town->school.valve_animation_calls = 0;
            step_set(town, town->step + 1);
        /* fall through */

        case 12:
            town->school.valve_animation_calls++;
            card_animation(town, 108, dt);
            break;

        default:
            
            ladder_unfreeze(town);
            finish(town);

            (town->border.state = SH_BORDER_FADEOUTSTART);
            (town->cam_active = town->script_use_cam = false);
            (town->school.empty_hand = false);
            break;
    }
}

static void roof_valve_hand_update(ShTown *town)
{
    if ((town->step != 7 && town->step != 12) || !town->school.hand_world_valid) { return; }
    int first;
    if (!sh_path_animation_first(&town->school.card_player, &first)) { return; }
    const int frame = town->school.valve_animation_calls > 2 ? (town->school.card_player.model.time >> 12) - first : 0;
    const int angle = sh_drain_valve_hand_angle(&town->school.hand_world);
    const unsigned sounds = sh_drain_valve_hand(&town->school.valve, town->step, angle, frame);
    static const float position[3] = {-10.500000000000f, 0.500000000000f, 12.899902343750f};
    if (sounds & SH_DRAIN_VALVE_SQUEAK) { sh_snd_at(1463, position, 0.5f); }
    if (sounds & SH_DRAIN_VALVE_CLICK) { sh_snd_at(1462, position, 0.5f); }
    if (sounds & SH_DRAIN_WATER_STOP) { sh_snd_stop(1465); }
    if (sounds & SH_DRAIN_WATER_START) { sh_snd_call(1465); }
}

static void roof_valve_loop_update(ShTown *town)
{
    if (!town->school.valve.running) { return; }
    const ShPathPoint camera = {SH_Q12(town->cam.pos[0]), -SH_Q12(town->cam.pos[1]), -SH_Q12(town->cam.pos[2])};
    const int32_t distance = sh_drain_water_distance(town->school.player_position, camera);
    static const float position[3] = {-10.199951171875f, 0.000000000000f, 13.349853515625f};
    const int balance = sh_snd_camera_balance(&town->cam, position) >> 1;
    sh_snd_update(1465, balance, sh_drain_water_attenuation(distance, town->school.valve.opening), 0);
}
